function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=110}
function updateHUD(){ui.snacks.textContent=hero.snacks;ui.size.textContent=hero.scale.toFixed(1)+'×';ui.progress.style.width=Math.max(0,Math.min(100,(hero.x/worldW)*100))+'%'}
function startGame(){state='play';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}
function finish(){state='win';ui.eyebrow.textContent='You made it!';ui.title.innerHTML='Sweet<br>sunset!';ui.message.innerHTML=`Rei found the sunset flag with <b>${hero.snacks} treats</b> and a cozy <b>${hero.scale.toFixed(1)}×</b> silhouette. What a peachy day!`;ui.start.textContent='Play again';ui.hint.textContent='Tip: hop over gaps and snack your way along the islands';ui.overlay.classList.remove('hidden')}
function reset(){hero.x=75;hero.scale=1;hero.snacks=0;hero.vx=0;hero.vy=0;hero.h=83;hero.y=groundY-hero.h;hero.invuln=0;food.forEach(f=>f.got=false);camera=0;updateHUD();startGame()}
function tick(dt,t){if(state!=='play')return;const speed=230/(1+(hero.scale-1)*.18);hero.vx=(keys.right?1:0)-(keys.left?1:0);hero.vx*=speed;if(hero.vx)hero.facing=Math.sign(hero.vx);if(keys.jump&&hero.grounded){hero.vy=-430;hero.grounded=false}hero.vy+=1050*dt;const oldBottom=hero.y+hero.h;hero.x=Math.max(12,Math.min(worldW-30,hero.x+hero.vx*dt));hero.y+=hero.vy*dt;hero.h=83*hero.scale;hero.grounded=false;let newBottom=hero.y+hero.h;if(hero.vy>=0){for(const p of platforms){if(hero.x+10*hero.scale>p.x&&hero.x-10*hero.scale<p.x+p.w&&oldBottom<=p.y+4&&newBottom>=p.y){hero.y=p.y-hero.h;hero.vy=0;hero.grounded=true;newBottom=p.y;break}}}if(hero.y>H+170){hero.x=Math.max(75,hero.x-190);hero.y=groundY-hero.h;hero.vy=0;hero.invuln=90;showToast('Whoops! Back to the sunny path 🌴')}if(hero.invuln>0)hero.invuln-=dt*60;
for(const f of food){if(f.got)continue;const fx=hero.x,fy=hero.y+hero.h*.54;if(Math.abs(f.x-fx)<22+hero.scale*8&&Math.abs(f.y-fy)<34){f.got=true;hero.snacks++;hero.scale=Math.min(2.1,1+hero.snacks*.095);hero.h=83*hero.scale;hero.y-=4;showToast(['Berry delicious! 🍓','Peachy! 🍑','A sweet little boost! 🍩','Sugar rush! 🍰'][f.kind])}}
camera=Math.max(0,Math.min(worldW-W,hero.x-W*.36));if(hero.x>worldW-160){finish();return}updateHUD()}
function render(t){drawBackground();for(const p of platforms)drawIsland(p);for(const f of food)drawFood(f,t);drawFlag();drawHero(t);if(state==='play'){ctx.fillStyle='#fff9';ctx.font='800 12px system-ui';ctx.textAlign='center';ctx.fillText('Find the flag ✦',W*.5,H-22)}}
function loop(t){if(state!=='play')return;const dt=Math.min(.032,(t-last)/1000||0);last=t;tick(dt,t);render(t);if(toastTimer>0&&--toastTimer===0)ui.toast.classList.remove('show');if(state==='play')requestAnimationFrame(loop)}
function press(name,on){keys[name]=on;if(name==='jump'&&on&&hero.grounded){hero.vy=-430;hero.grounded=false}}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','a','d','w'].includes(k))e.preventDefault();if(k==='arrowleft'||k==='a')press('left',true);if(k==='arrowright'||k==='d')press('right',true);if(k==='arrowup'||k==='w'||k===' ')press('jump',true);if((state==='title'||state==='win')&&(k==='enter'||k===' '))state==='win'?reset():startGame()});window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='arrowleft'||k==='a')press('left',false);if(k==='arrowright'||k==='d')press('right',false);if(k==='arrowup'||k==='w'||k===' ')press('jump',false)});window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));document.querySelectorAll('.touch').forEach(b=>{const key=b.dataset.control;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(key,true)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>press(key,false))});ui.start.addEventListener('click',()=>state==='win'?reset():startGame());
updateHUD();render(0);
})();
</script>
</body>
</html>

